// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this));
        vm.assume(caller != c.owner());
        vm.assume(newOwner != c.owner());

        address ownerBefore = c.owner();

        vm.prank(caller);
        bool ok = true;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }

        if (ok) {
            assertTrue(c.owner() == ownerBefore);
        }
    }
}
